import {specs,placements,defaultState,escapeHtml as e,required,checksFor,statusFor,inferSlot,cropKey,restoreState,logoPlacement} from './core.js';
import {contextThumbnails} from './context-thumbnails.js';
import {lobbyPads,lobbyFloorLine,lobbyCharacters,characterPlacement} from './lobby-layout.js';
import {openStorage,storeFile,deleteFile,storedFiles,inspectFile} from './storage.js';

const icons={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',image:'M3 3h18v18H3z M3 16l5-5 5 5 3-3 5 5 M15 7h.01',compare:'M12 3v18 M3 6h6v12H3z M15 6h6v12h-6z',check:'M4 12l5 5L20 6',settings:'M4 6h16 M4 12h16 M4 18h16 M8 3v6 M16 9v6 M10 15v6',upload:'M12 16V3 M7 8l5-5 5 5 M4 16v5h16v-5',download:'M12 3v13 M7 11l5 5 5-5 M4 17v4h16v-4',expand:'M9 3H3v6 M15 3h6v6 M3 15v6h6 M21 15v6h-6',phone:'M7 2h10v20H7z M10 18h4',spark:'M12 2l3 7 7 3-7 3-3 7-3-7-7-3 7-3z',layout:'M3 3h18v18H3z M3 14h18 M11 3v11',users:'M8 10a3 3 0 1 0 0-6 3 3 0 0 0 0 6 M2 21v-3a6 6 0 0 1 12 0v3 M16 4a3 3 0 0 1 0 6 M17 14a5 5 0 0 1 5 5v2',news:'M3 3h14v18H3z M17 7h4v14h-4 M6 7h8 M6 11h8 M6 15h4',message:'M3 3h18v14H9l-6 4z M7 8h10 M7 12h6',calendar:'M3 5h18v16H3z M3 10h18 M8 2v6 M16 2v6',arrow:'M5 12h14 M14 7l5 5-5 5',folder:'M3 7V4h7l3 3h8v14H3z',close:'M6 6l12 12 M18 6L6 18'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[n]||icons.image}"/></svg>`;
const app=document.querySelector('#app'),modal=document.querySelector('#modal');
let state=structuredClone(defaultState),assets={},removed=new Set(),storageOK=true,saveTimer,toastTimer,pending=[],importBusy=false;
try{const s=JSON.parse(localStorage.getItem('discovery-state')||'null');if(s)state=restoreState(s);removed=new Set(JSON.parse(localStorage.getItem('discovery-removed')||'[]'));}catch{storageOK=false;}
state.lobbyCount=Math.max(0,Math.min(4,Math.trunc(Number(state.lobbyCount)||0)));
if(!placements.some(p=>p.id===state.placement))state.placement='discover';
if(!['preview','library','compare','checklist','settings'].includes(state.page))state.page='preview';
const specOf=id=>specs.find(s=>s.id===id);
const keyOf=(slot,variant=state.variant)=>`${specOf(slot)?.group==='shared'?'shared':variant}:${slot}`;
const assetOf=(slot,variant=state.variant)=>assets[keyOf(slot,variant)];
const placement=()=>placements.find(p=>p.id===state.placement);
function save(){clearTimeout(saveTimer);saveTimer=setTimeout(()=>{try{localStorage.setItem('discovery-state',JSON.stringify(state));localStorage.setItem('discovery-removed',JSON.stringify([...removed]));}catch{storageOK=false;toast('Browser settings could not be saved.');}},180);}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4200);}
function activeSlot(){if(state.placement==='detail'&&/^screen[123]$/.test(state.detailMedia))return state.detailMedia;if(state.placement==='lobby')return 'lobby';if(state.placement==='hero')return 'landscapeArt';if(state.placement==='mobile')return state.mode==='text'?'portrait':'portraitArt';return state.mode==='text'?'landscape':'landscapeArt';}
const statusLabel={pass:'Checks pass',error:'Needs attention',unknown:'Review metadata',empty:'Not added'};
const badge=(a,s)=>`<span class="pill ${statusFor(a,s)}">${statusFor(a,s)==='pass'?'✓ ':''}${statusLabel[statusFor(a,s)]}</span>`;
function totals(variant=state.variant){let present=0,pass=0,issues=0,needed=0;for(const s of specs){const a=assetOf(s.id,variant);if(a)present++;if(statusFor(a,s)==='pass')pass++;if(a&&statusFor(a,s)!=='pass')issues++;if(required(s,state.profile)&&!a)needed++;}return {present,pass,issues,needed};}
function actualAsset(slot,variant){return assetOf(slot,variant);}
function art(slot,{variant=state.variant,composite=false,guide=state.guides}={}){
 const a=actualAsset(slot,variant),logo=assetOf('logo',variant),position=logoPlacement(state),crop=state.crop[cropKey(state,slot,variant)]||{x:50,y:50,zoom:100};
 let html=`<div class="preview-art" data-art="${slot}">`;
 html+=a&&!a.decodeError?`<img class="art-img" src="${e(a.url)}" alt="${e(specOf(slot)?.name||slot)}" style="object-position:${crop.x}% ${crop.y}%;transform:scale(${crop.zoom/100});transform-origin:${crop.x}% ${crop.y}%">`:`<div class="missing-art">${icon('image')}<span>Add ${e(specOf(slot)?.short||slot)}</span><small>Variant ${variant}${specOf(slot)?.group==='shared'?' · shared media':''}</small></div>`;
 if(composite&&logo)html+=`<img class="placed-logo" src="${e(logo.url)}" alt="Island logo" style="left:${position.x}%;top:${position.y}%;width:${position.width}%">`;
 if(guide&&a)html+='<div class="safe-guides"><span>UI OVERLAP · 15%</span></div>';
 return html+'</div>';
}
function nav(){return '<div class="fn-nav"><b>PLAY</b><span>SHOP</span><span>LOCKER</span><span>PASSES</span><span>QUESTS</span><span>COMPETE</span><span>CAREER</span><span>●</span></div>';}
function search(){return '<div class="fn-search"><strong>⌕ &nbsp; Search Discover</strong><b>DISCOVER</b><span>FOLLOWING</span><span>BY EPIC</span><span>RECENTS</span></div>';}
function footer(){return '<div class="fn-footer"><span>↵ &nbsp; CHAT</span><span>CUSTOM KEY</span><span>ESC &nbsp; BACK</span></div>';}
const contextById=new Map(contextThumbnails.map(tile=>[tile.id,tile]));
function contextTile(id){const tile=contextById.get(id);return '<div class="tile context" data-context-id="'+e(tile.id)+'"><img src="'+e(tile.src)+'" alt="'+e(tile.title)+' reference thumbnail" draggable="false"><span class="counter" aria-label="Example player count">'+e(tile.examplePlayers)+'</span></div>';}
function islandTile(variant,slot=activeSlot()){return `<div class="tile selected">${art(slot,{variant,composite:slot.endsWith('Art')})}<span class="counter">${e(state.count)}</span></div>`;}
function discoverStage(variant){return nav()+search()+`<section class="fn-row" style="top:27%"><h3>For You<small>Based on Your Play History</small></h3><div class="fn-tiles">${contextTile('bodycam')}${islandTile(variant)}${['xeno-legend','zombies-vs-human','mega-red-blue','piece-control'].map(contextTile).join('')}</div></section><section class="fn-row" style="top:53%"><h3>Simulation &amp; Tycoon</h3><div class="fn-tiles">${['droid-tycoon','farm-simulator','steal-an-egg','go-up-brainrots','asmr-tycoon','cash-city'].map(contextTile).join('')}</div></section><section class="fn-row" style="top:77%"><h3>Party &amp; Mini Games</h3><div class="fn-tiles">${['pillars','super-pillars','murder-mystery','bed-wars','lava-pillars','run-and-scream'].map(contextTile).join('')}</div></section>`+footer();}
function heroStage(variant){const trailer=assetOf('trailer',variant);return nav()+search()+`<div class="fn-hero">${art('landscapeArt',{variant,composite:state.showBannerLogo})}${state.useVideo&&trailer?`<video class="hero-video" src="${e(trailer.url)}" controls muted playsinline poster="${e(assetOf('landscapeArt',variant)?.url||'')}"></video>`:''}<div class="hero-actions"><h2 class="hero-map-name">${e(state.title)}</h2><div class="hero-button-row"><span class="play-pill">PLAY</span><span class="hero-more" role="img" aria-label="More options button preview"><i></i><i></i><i></i></span></div></div><div class="hero-rating" role="img" aria-label="ESRB Teen rating badge · reference example"><img src="assets/esrb-teen.svg" alt=""></div></div><section class="fn-row" style="top:66%"><h3>Featured By Epic</h3><div class="fn-tiles large">${islandTile(variant,'landscape')}${['every-gun','the-pit','go-goated'].map(contextTile).join('')}</div></section>`+footer();}
// An empty pad's top is a mirror: a stage-sized copy of the lobby picture, flipped about the floor line, seen through the pad.
function padMirror(pad,variant){
 const a=actualAsset('lobby',variant);if(!a||a.decodeError)return '';
 return '<div class="pad-mirror" style="width:'+(100/pad.width*100)+'%;height:'+(100/pad.height*100)+'%;left:'+(-(pad.x-pad.width/2)/pad.width*100)+'%;top:'+(-(pad.y-pad.height/2)/pad.height*100)+'%;transform-origin:50% '+lobbyFloorLine+'%">'+art('lobby',{variant,guide:false})+'</div>';
}
function lobbyFigure(variant){
 const count=Number(state.lobbyCount);
 // Far pads first, so the nearer pads overlap them.
 const pads=lobbyPads.map((pad,i)=>({pad,occupied:i<count})).sort((a,b)=>a.pad.y-b.pad.y);
 const placed=lobbyCharacters.slice(0,count).map((c,i)=>({c,pad:lobbyPads[i],p:characterPlacement(c,lobbyPads[i])}));
 // Contact shadows sit on the pads, under every character; nearer pads' characters draw over farther ones.
 const shadows=placed.flatMap(({p})=>p.shadows).map(s=>'<i class="lobby-foot-shadow" style="left:'+s.x+'%;top:'+s.y+'%;width:'+s.width+'%;height:'+s.height+'%"></i>').join('');
 return '<div class="lobby-party" role="group" aria-label="'+count+' lobby characters">'+pads.map(({pad,occupied})=>'<div class="party-platform'+(occupied?' occupied':'')+'" data-pad="'+pad.id+'" style="left:'+pad.x+'%;top:'+pad.y+'%;width:'+pad.width+'%;height:'+pad.height+'%" aria-hidden="true"><i class="pad-side"></i><i class="pad-bevel"></i><i class="pad-top">'+(occupied?'':padMirror(pad,variant))+'</i></div>').join('')+shadows+placed.map(({c,pad,p})=>{
  const [x,y,w,h]=c.bounds,src='assets/characters/'+c.file+'.png',crop='width:'+(2048/w*100)+'%;height:'+(2048/h*100)+'%;left:'+(-x/w*100)+'%;top:'+(-y/h*100)+'%';
  // The lit pad lights the bottom of each shoe: a cyan copy of the cutout, masked to an ellipse over each sole.
  const glow=c.soles.map(([fx,,,ty,fw])=>'radial-gradient('+(fw*.8/20.48)+'% '+(85/20.48)+'% at '+(fx/20.48)+'% '+(ty/20.48)+'%,#000 25%,transparent)').join(',');
  return '<div class="lobby-character" data-character="'+c.file+'" style="left:'+p.left+'%;bottom:'+p.bottom+'%;height:'+p.height+'%;aspect-ratio:'+w+'/'+h+';transform:translateX(-'+p.anchor+'%);z-index:'+Math.round(pad.y)+'"><img src="'+src+'" alt="'+c.alt+'" draggable="false" style="'+crop+'"><img class="sole-light" src="'+src+'" alt="" draggable="false" style="'+crop+';-webkit-mask-image:'+glow+';mask-image:'+glow+'"></div>';
 }).join('')+'</div>';
}
// The glossy floor mirrors the lobby picture about the floor line: crisp near the line, rougher farther down.
function floorReflection(variant){
 const a=actualAsset('lobby',variant);if(!a||a.decodeError)return '';
 const layer=cls=>'<div class="'+cls+'"><div class="reflection-flip">'+art('lobby',{variant,guide:false})+'</div></div>';
 return '<div class="lobby-reflection" style="--floor:'+lobbyFloorLine+'%" aria-hidden="true">'+layer('reflection-rough')+layer('reflection-crisp')+'</div>';
}
function lobbyControls(){return '<div class="inspector-section"><h3>Lobby party</h3><label class="field">Characters<select data-field="lobbyCount">'+[0,1,2,3,4].map(n=>'<option value="'+n+'" '+(Number(state.lobbyCount)===n?'selected':'')+'>'+n+' — '+(n===0?'Empty lobby':n===1?'Solo':n===4?'Full party':n+' characters')+'</option>').join('')+'</select></label><p class="help">Fixed lineup on the measured 16:9 pad layout. Friend activity is sample UI; floor lighting is simulated.</p></div>';}
function mobileStage(variant){return `<div class="mobile-top"><span>9:41</span><span>▰ ▰ ●</span></div><div class="mobile-title">Discover</div><div class="mobile-search">⌕ &nbsp; Find your next favorite</div><div class="mobile-poster">${art(activeSlot(),{variant,composite:state.mode==='composite'})}<span class="counter">● ${e(state.count)} playing</span></div><div class="mobile-copy"><strong>${e(state.title)}</strong><small>By ${e(state.creator)}</small><span class="play-pill">PLAY</span></div><div class="mobile-nav"><span>◈ &nbsp; DISCOVER</span><span>♡ &nbsp; LIBRARY</span><span>◉ &nbsp; PROFILE</span></div>`;}
function detailStage(variant){const video=assetOf(state.video,variant);return '<header class="detail-heading"><p>Created by · <span>'+e(state.creator)+'</span></p><h2>'+e(state.title)+'</h2></header><div class="detail-main-media">'+(state.useVideo&&video?'<video src="'+e(video.url)+'" controls playsinline></video>':art(activeSlot(),{variant,composite:state.mode==='composite'&&!activeSlot().startsWith('screen')}))+'</div><aside class="detail-about"><h3>About Island</h3><div class="detail-facts"><p>'+gameIcon('users')+'<span>'+e(state.count)+' Playing Now</span></p><p>'+gameIcon('refresh')+'<span>Updated '+e(state.updated)+'</span></p><p>'+gameIcon('clock')+'<span>Released '+e(state.released)+'</span></p><p class="detail-code">'+gameIcon('island')+'<span>'+e(state.islandCode)+' '+gameIcon('copy')+'</span></p><hr>'+'<p>'+gameIcon('users')+'<span>Up to '+e(state.maxPlayers)+' Players</span></p></div></aside><div class="detail-rating" aria-label="Example ESRB Teen rating"><div class="detail-rating-icon"><img src="assets/esrb-teen.svg" alt="ESRB Teen"></div><div><strong>Teen</strong><span>Violence</span><hr><small>Users Interact, In-Game Purchases</small></div></div><div class="detail-actions"><span class="detail-select">SELECT</span><span aria-label="Like">'+gameIcon('thumb')+'</span><span class="dislike" aria-label="Dislike">'+gameIcon('thumb')+'</span><i></i><span class="detail-favorites">'+gameIcon('heart')+e(state.favorites)+'</span><span class="detail-more" aria-label="More options">•••</span></div><div class="detail-highlights"><h3>Community Events &amp; Highlights</h3><div class="detail-highlight-row">'+['screen1','screen2','screen3'].map(s=>'<div>'+art(s,{variant,guide:false})+'</div>').join('')+'<div>'+art('landscape',{variant,guide:false})+'</div></div></div><div class="detail-footer"><span>VIEW DEVELOPER</span><span><kbd>ESC</kbd> BACK</span></div>';}
const gamePaths={users:'M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M2 22v-4a7 7 0 0 1 14 0v4 M18 4a3 3 0 0 1 0 6 M19 14a5 5 0 0 1 4 5v3',refresh:'M20 8a9 9 0 0 0-16-2 L2 9 M2 3v6h6 M4 16a9 9 0 0 0 16 2l2-3 M22 21v-6h-6',clock:'M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20 M12 5v7h5',island:'M2 22h20 M3 21c4-5 14-5 18 0 M12 17V7 M12 7C7 0 4 2 2 6 M12 7c1-8 7-7 10-3 M12 7C6 3 4 7 3 11 M12 7c4-5 7-1 9 3',copy:'M8 3h13v15H8z M3 8v14h14',thumb:'M3 10h4v11H3z M7 10l5-8h3v7h6l-2 12H7',heart:'M12 21 3 12C-3 5 6-2 12 5c6-7 15 0 9 7L12 21',sliders:'M2 5h20 M2 12h20 M2 19h20 M7 2v6 M16 9v6 M9 16v6'};
function gameIcon(name){return '<svg class="game-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="'+gamePaths[name]+'"/></svg>';}
function lobbyNav(){return '<div class="lobby-navigation"><b>PLAY</b><span>SHOP</span><span>LOCKER</span><span>PASSES</span><span>QUESTS</span><span>COMPETE</span><span>CAREER</span><span class="lobby-currency">Ⓥ 1,950</span></div><div class="lobby-profile"><img src="assets/characters/wave.png" alt=""><i></i></div>';}
function lobbyStage(variant){const count=Number(state.lobbyCount);return '<div class="lobby-bg">'+art('lobby',{variant,guide:false})+'</div>'+floorReflection(variant)+'<div class="lobby-floor" aria-hidden="true"></div><div class="lobby-shade"></div>'+lobbyFigure(variant)+lobbyNav()+'<div class="lobby-news">'+art('landscape',{variant,guide:false})+'<div class="lobby-news-title">'+e(state.postTitle)+'</div><div class="lobby-news-dots"><b></b><i></i><i></i><i></i><i></i></div></div>'+(count>0?'<div class="player-name"><span class="player-level">103</span><div>'+e(state.creator)+' <span class="player-platform">▣</span><small>Not Ready</small></div></div>':'')+lobbyPads.slice(1).map((pad,index)=>index+1<count?'':(index<3?'<div class="lobby-friend" data-friend="'+index+'" style="left:'+pad.x+'%" aria-label="Example friend activity"><div class="friend-avatar"><div class="friend-portrait" data-character="'+lobbyCharacters[index+1].file+'"><img src="assets/characters/'+lobbyCharacters[index+1].file+'.png" alt=""></div><i></i></div><div class="friend-card"><strong>Friend '+(index+1)+' <small>▣</small></strong><span>'+(index===2?'Joinable Game':'Playing an island')+'</span></div></div>':'')+'<div class="lobby-invite" style="left:'+pad.x+'%" aria-label="Empty party position">+</div>').join('')+'<div class="lobby-play"><h2>'+e(state.title)+'</h2><div class="lobby-public">'+gameIcon('sliders')+' Public</div><span class="play-pill">PLAY</span></div><div class="lobby-level"><div><small>LVL</small><b>103</b></div></div><div class="lobby-music"><span>♫</span></div><div class="lobby-footer"><span><kbd>↵</kbd> CHAT</span><span><kbd>B</kbd> EMOTE</span><span>BACK</span></div><div class="lobby-peek">'+['super-pillars','droid-tycoon','pillars','farm-simulator','bed-wars','xeno-legend'].map(contextTile).join('')+'</div>'+(state.guides?'<div class="lobby-safe"><div class="nav-zone">TOP NAVIGATION</div>'+(count>0?'<div class="avatar-zone">CHARACTER OVERLAP</div>':'')+'</div>':'');}
function newsFooter(post=false){return '<div class="news-dots"><span>‹</span><i></i><i></i><i></i><i></i><b></b><span>›</span></div><div class="news-footer">'+(post?'<span>REPORT POST</span>':'')+'<span><kbd>ESC</kbd> CLOSE</span></div>';}
function newsStage(variant){return '<div class="news-panel">'+art(activeSlot(),{variant,composite:state.mode==='composite'})+'<div class="news-copy"><div><h2>'+e(state.headline)+'</h2><p>'+e(state.newsTagline)+'</p></div><span class="play-pill">PLAY NOW</span></div></div>'+newsFooter();}
function postStage(variant){return '<div class="post-panel"><div class="post-copy"><small>● '+e(state.creator)+' · '+e(state.title)+' · 3d ago</small><h2>'+e(state.postTitle)+'</h2><p>'+e(state.postBody)+'</p></div><div class="post-media">'+art(activeSlot(),{variant,composite:state.mode==='composite'})+'</div><div class="post-reactions"><span>👍 1.2K</span><span>↗ VIEW REPLIES</span></div></div>'+newsFooter(true);}
function eventStage(variant){return nav()+search()+`<h3 class="events-heading">Community Events</h3><div class="event-grid">${[0,1,2,3].map((n)=>`<div class="event-card"><div class="event-img">${n===1?art(activeSlot(),{variant,composite:state.mode==='composite'}):contextTile(['murder-mystery',null,'super-pillars','run-and-scream'][n])}</div><div class="event-body"><div class="event-date">Soon<b>—</b></div><div class="event-info"><small>Upcoming · For 1 hour</small><h3>${n===1?e(state.eventTitle):['COMMUNITY EVENT','','ISLAND EVENT','UPCOMING EVENT'][n]}</h3><span>${n===1?e(state.eventTagline):'Join the community'}</span></div></div><footer><span>${n===1?e(state.creator):'Community creator'}</span><span>1d ago</span></footer></div>`).join('')}</div>`+footer();}
function stageMarkup(variant=state.variant,id='preview-stage'){
 const p=state.placement;let content='';if(!state.ui)content=art(activeSlot(),{variant,composite:p==='hero'?state.showBannerLogo:state.mode==='composite'});else content=({discover:discoverStage,hero:heroStage,mobile:mobileStage,detail:detailStage,lobby:lobbyStage,news:newsStage,post:postStage,event:eventStage}[p])(variant);
 return `<div id="${id}" class="stage ${p==='mobile'?'mobile-stage':p+'-stage'} ${!state.ui?'raw-stage':''}" ${p!=='mobile'?`style="aspect-ratio:${p==='lobby'||p==='detail'?'16/9':state.ratio}"`:''} role="group" aria-label="${e(placement().label)} simulation for variant ${variant}">${content}</div>`;
}
function render(){
 if(state.placement==='hero')state.mode='composite';
 const t=totals(),titles={preview:['Preview lab','Every placement. One place to get it right.'],library:['Media library','Add your artwork once. Preview it everywhere.'],compare:['Compare variants','Judge the composition before you run a live A/B test.'],checklist:['Delivery checklist','File checks for your Creator Portal media package.'],settings:['Island details','The text and example data used throughout your previews.']};
 app.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">${icon('layout')}</div><div>DISCOVERY<small>STUDIO</small></div></div><button class="project" data-page="settings"><img class="project-thumb" src="${e(assetOf('landscape','A')?.url||'assets/landscape_comp.jpeg')}" alt=""><div><strong>${e(state.title)}</strong><span>Island workspace &nbsp;⌄</span></div></button><div class="eyebrow nav-title">Workspace</div><nav>${[['preview','grid','Preview lab'],['library','image','Media library'],['compare','compare','Compare variants'],['checklist','check','Delivery checklist']].map(([id,ic,label])=>`<button class="nav-item ${state.page===id?'active':''}" data-page="${id}" ${state.page===id?'aria-current="page"':''}>${icon(ic)}${label}${id==='library'?`<span class="nav-count">${t.present}</span>`:''}</button>`).join('')}<button class="nav-item ${state.page==='settings'?'active':''}" data-page="settings">${icon('settings')}Island details</button></nav><div class="sidebar-bottom"><div class="local-note"><strong><span class="dot"></span>Your creative workspace</strong>Imported files stay in this browser. Changes save on this device.</div><div class="sidebar-foot"><span class="avatar">PC</span><div>Puzzler Creations<br><span class="muted tiny">UEFN creator tools</span></div></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">CREATOR TOOLS <span>/</span> <strong>Discovery Studio</strong> <span class="pill">BETA 0.1</span></div><div class="save-state"><span class="dot"></span>${storageOK?'Saved on this device':'Session only · storage unavailable'}</div></header><div class="workspace"><div class="page-heading"><div><h1>${titles[state.page][0]}</h1><p>${titles[state.page][1]}</p></div><div class="heading-actions"><button class="btn" data-action="import">${icon('upload')}Import media</button>${state.page==='preview'||state.page==='compare'?`<button class="btn primary" data-action="export">${icon('download')}Export preview</button>`:`<button class="btn primary" data-action="report">${icon('download')}Export checklist</button>`}</div></div><div id="page-content">${({preview:previewPage,library:libraryPage,compare:comparePage,checklist:checklistPage,settings:settingsPage}[state.page])()}</div><p class="footnote">Independent composition tool. Previews are approximations; example counts and dates are illustrative. Actual Fortnite placement, crops and UI can vary.</p><p class="footnote">Portions of the materials used are trademarks and/or copyrighted works of Epic Games, Inc. All rights reserved by Epic. This material is not official and is not endorsed by Epic.</p></div></main></div>`;
 save();
}
function placementTabs(){return `<div class="placement-tabs" role="tablist" aria-label="Preview placement">${placements.map(p=>`<button class="placement-tab ${p.id===state.placement?'active':''}" data-placement="${p.id}" role="tab" aria-selected="${p.id===state.placement}">${icon(p.icon)}${p.name}</button>`).join('')}</div>`;}
function variantSegments(){return `<div class="segments" aria-label="Asset variant">${['A','B'].map(v=>`<button data-variant="${v}" class="${state.variant===v?'active':''}" aria-pressed="${state.variant===v}">${v}</button>`).join('')}</div>`;}
function bannerLogoToggle(){return `<label class="switch-row">Show logo on banner<input type="checkbox" data-field="showBannerLogo" ${state.showBannerLogo?'checked':''}></label>`;}
function toolbar(){return `<div class="stage-toolbar"><div class="stage-toolbar-left">${variantSegments()}${state.placement==='hero'?`<span class="tiny muted">${state.showBannerLogo?'Art + logo':'Art only'}</span>`:`<select aria-label="Artwork mode" data-field="mode"><option value="text" ${state.mode==='text'?'selected':''}>With text</option><option value="composite" ${state.mode==='composite'?'selected':''}>Art + logo</option></select>`}</div><div class="stage-toolbar-left">${state.placement==='mobile'?'<span class="tiny muted">Portrait · 3:4 artwork</span>':['lobby','detail'].includes(state.placement)?'<span class="tiny muted">Reference · 1920 × 1080</span>':`<select aria-label="Preview aspect ratio" data-field="ratio">${[['16/9','Desktop · 16:9'],['21/9','Ultrawide · 21:9'],['4/3','Classic · 4:3']].map(([v,n])=>`<option value="${v}" ${state.ratio===v?'selected':''}>${n}</option>`).join('')}</select>`}<button class="icon-button" title="Expand preview" aria-label="Expand preview" data-action="expand">${icon('expand')}</button></div></div>`;}
function previewPage(){const t=totals();return placementTabs()+`<div class="preview-layout"><div><div class="stage-panel">${toolbar()}<div class="stage-wrap" id="stage-mount">${stageMarkup()}</div><div class="stage-caption"><span><span class="dot"></span><strong id="placement-caption">${e(placement().label)}</strong> · ${state.ui?'In-game simulation':'Artwork only'}</span><span>${placement().calibrated?'Calibrated to in-game screenshots':'Illustrative layout'}</span></div></div><div class="readiness"><div class="status-icon">${icon(t.issues||t.needed?'image':'check')}</div><div><strong>${t.pass} of ${specs.length} assets pass file checks</strong><p>${t.issues?t.issues+' need attention · ':''}${t.needed?t.needed+' required missing':'Required uploads present'} · Content review remains manual</p></div><button class="btn subtle small" data-page="checklist">View checklist ${icon('arrow')}</button></div><div class="quick-title"><h2>Your artwork, at a glance</h2><button class="muted tiny" data-page="library">Manage media ↗</button></div><div class="quick-cards">${[['landscape','Discover thumbnail','1920 × 1080 · 16:9','discover'],['portrait','Portrait thumbnail','1440 × 1920 · 3:4','mobile'],['logo','Isolated logo','1440 × 608 · transparent','hero']].map(([s,n,d,p])=>`<button class="quick-card" data-placement="${p}"><div class="quick-image">${assetOf(s)?`<img src="${e(assetOf(s).url)}" alt="${n}">`:`<div class="muted tiny">No ${n.toLowerCase()} added</div>`}</div><strong>${n} <b>↗</b></strong><span>${d}</span></button>`).join('')}</div></div>${inspector()}</div>`;}
function inspector(){const logo=logoPlacement(state),s=specOf(activeSlot()),a=assetOf(s.id),c=state.crop[cropKey(state,s.id)]||{x:50,y:50,zoom:100};return `<aside class="inspector"><div class="inspector-title"><span>Composition</span>${icon('settings')}</div>${state.placement==='lobby'?lobbyControls():''}${state.placement==='hero'?`<div class="inspector-section"><h3>Banner details</h3><label class="field">Map name<input data-text="title" value="${e(state.title)}" maxlength="80"></label>${bannerLogoToggle()}<p class="help">The map name appears above Play. The T/ESRB badge is an example rating, placed as it appears in game.</p></div>`:''}<div class="inspector-section"><h3>Source artwork</h3>${state.placement==='detail'?'<label class="field">Main media<select data-field="detailMedia">'+[['thumbnail','Island thumbnail'],['screen1','Screenshot 1'],['screen2','Screenshot 2'],['screen3','Screenshot 3']].map(([v,n])=>'<option value="'+v+'" '+(state.detailMedia===v?'selected':'')+'>'+n+'</option>').join('')+'</select></label>':''}<div class="asset-selected">${a?`<img src="${e(a.url)}" alt="">`:icon('image')}<p><strong>${e(s.short)}</strong>${a?`${a.width||'?'} × ${a.height||'?'} px · ${state.variant}`:'No media in this slot'}</p></div><button class="btn small" data-upload="${s.id}">${icon('upload')}${a?'Replace':'Add'} artwork</button>${state.placement==='hero'?'<p class="help" style="margin-top:10px">Featured uses art-only landscape with an optional isolated logo overlay.</p>':''}</div><div class="inspector-section"><h3>Preview framing</h3>${[['x','Horizontal focus',c.x,0,100,'%'],['y','Vertical focus',c.y,0,100,'%'],['zoom','Zoom',c.zoom,100,180,'%']].map(([id,n,v,min,max,u])=>`<label class="range-label" for="crop-${id}">${n}<output id="out-crop-${id}">${v}${u}</output></label><input id="crop-${id}" aria-label="${n}" type="range" min="${min}" max="${max}" value="${v}" data-crop="${id}">`).join('')}<button class="muted tiny" data-action="reset-crop" style="margin-top:10px">Reset framing ↺</button><p class="help" style="margin-top:10px">Simulation only. Original upload dimensions and pixels are preserved.</p></div>${state.placement!=='lobby'&&!activeSlot().startsWith('screen')&&(state.placement==='hero'?state.showBannerLogo:state.mode==='composite')?`<div class="inspector-section"><h3>Logo placement</h3>${[['x','Horizontal',0,100],['y','Vertical',0,100],['width','Width',10,90]].map(([id,n,min,max])=>`<label class="range-label" for="logo-${id}">${n}<output id="out-logo-${id}">${logo[id]}%</output></label><input id="logo-${id}" type="range" min="${min}" max="${max}" value="${logo[id]}" data-logo="${id}">`).join('')}<p class="help">Saved for ${e(placement().name)} only. Other placements keep their own logo position.</p></div>`:''}<div class="inspector-section"><h3>Preview layers</h3><label class="switch-row">In-game UI<input type="checkbox" data-field="ui" ${state.ui?'checked':''}></label><label class="switch-row">Safe-area guides<input type="checkbox" data-field="guides" ${state.guides?'checked':''}></label>${['hero','detail'].includes(state.placement)?`<label class="field" style="margin-top:15px">Video source<select data-field="video"><option value="trailer" ${state.video==='trailer'?'selected':''}>Trailer</option><option value="gameplay" ${state.video==='gameplay'?'selected':''}>Gameplay</option></select></label><label class="switch-row">Show video<input type="checkbox" data-field="useVideo" ${state.useVideo?'checked':''}></label><p class="help" style="margin-top:8px">${assetOf(state.placement==='hero'?'trailer':state.video)?'Use the video controls to play.':'Add a '+(state.placement==='hero'?'trailer':state.video)+' in Media library.'}</p>`:''}</div><div class="inspector-section"><p class="help">${e(placement().note)}</p>${state.guides?'<p class="help" style="margin-top:10px">Thumbnail guides mark the upper/lower 15% as UI risk areas. They are a design aid, not a guaranteed safe region.</p>':''}</div></aside>`;}
function assetCard(s){const a=assetOf(s.id),req=required(s,state.profile);return `<article class="asset-card" data-drop-slot="${s.id}"><button class="asset-thumb" data-${a?'inspect':'upload'}="${s.id}" style="width:100%" aria-label="${a?'Inspect':'Add'} ${e(s.name)}">${a?(s.video?`<div class="empty-slot">${icon('news')}<span>${e(a.name)}</span><span>${a.duration?a.duration.toFixed(1)+' seconds':'Metadata unavailable'}</span></div>`:`<img src="${e(a.url)}" alt="${e(s.name)}">`):`<span class="empty-slot">${icon('upload')}<span>Drop file or click to add</span></span>`}</button><div class="asset-info"><div class="asset-card-top"><h3>${e(s.name)}</h3>${badge(a,s)}</div><p>${s.w} × ${s.h} px · &lt; ${s.max} MB${s.video?' · 10–40 sec':''}</p><p>${s.ext.join(' / ').toUpperCase()} · ${req?'Required':s.future?'Optional until October 22':'Optional'}${s.alpha?' · Transparent':''}</p><div class="asset-name">${a?e(a.name):'No file added'}</div><div class="asset-actions"><button class="btn small" data-upload="${s.id}">${a?'Replace':'Add file'}</button>${a?`<button class="btn small subtle" data-inspect="${s.id}">Inspect</button><button class="btn small subtle" data-remove="${s.id}" aria-label="Remove ${e(s.name)}">×</button>`:''}</div></div></article>`;}
function libraryPage(){return `<div class="full-note">Uploads stay in this browser using local storage. A and B keep their own five thumbnail/logo files; video, screenshots and lobby media are shared. Drag files onto an individual slot, or use Import media to assign a batch.</div><div class="section-heading"><div class="variant-heading"><h2>Promotional artwork</h2>${variantSegments()}</div><button class="btn small" data-action="copy-variant">Copy ${state.variant} to ${state.variant==='A'?'B':'A'}</button></div><div class="asset-grid">${specs.filter(s=>s.group==='variant').map(assetCard).join('')}</div><div class="section-heading"><div><h2>Videos, screenshots &amp; lobby</h2><p>Shared across both variants · three screenshot slots</p></div></div><div class="asset-grid">${specs.filter(s=>s.group==='shared').map(assetCard).join('')}</div>`;}
function comparePage(){return `<div class="compare-tools"><label>Placement<select data-field="placement">${placements.filter(p=>p.id!=='lobby').map(p=>`<option value="${p.id}" ${state.placement===p.id?'selected':''}>${p.label}</option>`).join('')}</select></label>${state.placement==='hero'?bannerLogoToggle():`<label>Artwork<select data-field="mode"><option value="text" ${state.mode==='text'?'selected':''}>With text</option><option value="composite" ${state.mode==='composite'?'selected':''}>Art + logo</option></select></label>`}<button class="btn small" data-action="copy-variant">Copy ${state.variant} to ${state.variant==='A'?'B':'A'}</button></div><div class="comparison" id="comparison-capture">${['A','B'].map(v=>`<section class="stage-panel"><div class="compare-heading"><strong>Variant ${v}</strong><span>${totals(v).pass} files pass checks</span></div><div class="stage-wrap">${stageMarkup(v,'preview-'+v)}</div>${!assetOf(activeSlot(),v)?`<div class="empty-variant">Variant ${v} is empty for this placement. Add its artwork in Media library. Files are never borrowed from the other variant.</div>`:''}</section>`).join('')}</div><div class="review-box"><h3>A visual comparison, before the live test</h3><p>Compare legibility, focal points and logo contrast at the same display size. This tool does not create a Creator Portal test or estimate engagement. Each variant remains a complete, separate artwork set.</p></div>`;}
function checklistPage(){const t=totals();return `<div class="check-toolbar"><label>Requirement profile<select data-field="profile"><option value="current" ${state.profile==='current'?'selected':''}>Creator Portal · October 11, 2026</option><option value="oct22" ${state.profile==='oct22'?'selected':''}>Creator Portal · October 22 changes</option></select></label>${variantSegments()}<span class="pill ${t.needed||t.issues?'unknown':''}">${t.pass} pass · ${t.needed} required missing</span></div><table class="check-table"><thead><tr><th>Asset</th><th>Required size</th><th>Requirement</th><th>File checks</th></tr></thead><tbody>${specs.map(s=>{const a=assetOf(s.id),bad=checksFor(a,s).filter(c=>c.ok!==true);return `<tr><td><button data-inspect="${s.id}">${e(s.name)}</button>${bad.length?`<div class="check-reasons">${bad.map(c=>e(c.name+': '+c.detail)).join('<br>')}</div>`:''}</td><td>${s.w} × ${s.h}<br>&lt; ${s.max} MB${s.video?' · 10–40 sec':''}</td><td>${required(s,state.profile)?'Required':'Optional'}</td><td>${badge(a,s)}</td></tr>`;}).join('')}</tbody></table><div class="review-box"><h3>Content review · variant ${state.variant}</h3><p>File checks verify type, dimensions, size, video duration where readable, and transparent pixels in the logo. They cannot verify policy compliance, identify baked-in text or logos, or confirm that footage is unedited.</p>${[['art','Art-only thumbnails contain no text, logos or calls to action.'],['accuracy','Images accurately represent my island and screenshots show real gameplay.'],['video','Trailer suitability and unedited gameplay requirements have been reviewed, where supplied.'],['lobby','Lobby composition and applicable content guidelines have been reviewed.']].map(([key,label])=>`<label><input type="checkbox" data-review="${key}" ${state.review[state.variant+':'+key]?'checked':''}>${label}</label>`).join('')}</div><div class="sources"><strong>Specification source</strong><p>Validation follows the Creator Portal upload limits as of October 11, 2026. The “October 22” profile follows Epic’s notice of upcoming changes; it is not a live publishing guarantee. File sizes use decimal MB; the limit is strictly less than the stated maximum.</p><p>Epic’s public production recommendations mention 15–30-second ProRes MOV video, while the Creator Portal accepts 10–40 seconds in MP4, MKV, WEBM or MOV. This tool checks the Portal upload limits. Unsupported browser codecs are marked for manual metadata review.</p><a href="https://dev.epicgames.com/documentation/fortnite/making-thumbnails-and-videos-in-fortnite-creative" target="_blank" rel="noopener">Thumbnail &amp; video guidance ↗</a><a href="https://dev.epicgames.com/documentation/fortnite/promotional-media-screen-in-fortnite" target="_blank" rel="noopener">Promotional media ↗</a><a href="https://dev.epicgames.com/documentation/fortnite/lobby-background-image-guidelines-in-fortnite-creative" target="_blank" rel="noopener">Lobby guidelines ↗</a></div>`;}
function settingsPage(){return `<div class="settings-grid"><section class="settings-panel"><h3>Island identity</h3>${[['title','Island title',80],['creator','Creator name',50],['count','Example player count',12]].map(([id,n,max])=>`<label class="field">${n}<input data-text="${id}" value="${e(state[id])}" maxlength="${max}"></label>`).join('')}<label class="field">Island description<textarea data-text="description" maxlength="260">${e(state.description)}</textarea></label><p class="help">These fields change the simulated UI. They do not modify text already baked into your images.</p></section><section class="settings-panel"><h3>News, creator post &amp; events</h3>${[['headline','News headline'],['newsTagline','News tagline'],['postTitle','Creator update headline'],['postBody','Creator update text'],['eventTitle','Event title'],['eventTagline','Event tagline']].map(([id,n])=>`<label class="field">${n}<input data-text="${id}" value="${e(state[id])}" maxlength="180"></label>`).join('')}<p class="help">Event times, dates and engagement figures are static examples for composition.</p></section><section class="settings-panel"><h3>Island Details metadata</h3>${[['islandCode','Island code'],['updated','Updated date'],['released','Release date'],['maxPlayers','Maximum players'],['favorites','Example favorite count']].map(([id,n])=>'<label class="field">'+n+'<input data-text="'+id+'" value="'+e(state[id])+'" maxlength="40"></label>').join('')}<p class="help">Example values for the preview. The T/ESRB panel is an example rating, as shown in game.</p></section></div><div class="review-box"><h3>About this workspace</h3><p>The starter contains the Arcade Chess media. New uploads are stored only in this browser’s IndexedDB; nothing is sent to a server. Browser storage is device- and origin-specific and can be cleared by the browser. Keep your original media files. PNG exports capture a preview composition; checklist exports contain metadata, not original media.</p><p>Surrounding tiles use a saved set of real thumbnails sourced via <a href="https://fortnite.gg/discover" target="_blank" rel="noopener noreferrer">Fortnite.gg Discover</a>. These are reference images; player counts and row placement are illustrative.</p></div>`;}
function updateStage(){if(state.page==='preview'){document.querySelector('#stage-mount').innerHTML=stageMarkup();}else if(state.page==='compare'){document.querySelector('#page-content').innerHTML=comparePage();}}
function showModal(title,description,body,footer=''){modal.classList.remove('wide');modal.innerHTML=`<div class="modal-heading"><div><h2 id="modal-title">${e(title)}</h2><p>${e(description)}</p></div><button data-action="close-modal" aria-label="Close dialog">×</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}`;modal.setAttribute('aria-labelledby','modal-title');if(!modal.open)modal.showModal();}
function inspect(slot){const s=specOf(slot),a=assetOf(slot);if(!a){chooseFile(slot);return;}const c=checksFor(a,s);showModal(s.name,a.name,`${s.video?`<video class="inspect-image" src="${e(a.url)}" controls playsinline></video>`:`<img class="inspect-image" src="${e(a.url)}" alt="${e(s.name)}">`}<div class="inspect-checks">${c.map(x=>`<div class="inspect-check"><div>${x.name}<small>${e(x.detail)}</small></div><span class="pill ${x.ok===true?'':x.ok===false?'error':'unknown'}">${x.ok===true?'Pass':x.ok===false?'Needs attention':'Manual review'}</span></div>`).join('')}</div>${s.manual?`<p class="warning-line">Manual check: ${e(s.manual)}.</p>`:''}${s.alpha?'<p class="help">A transparent pixel check does not establish that the logo is correctly isolated. Review the checkerboard preview.</p>':''}`,`<button class="btn" data-upload="${s.id}">Replace file</button><button class="btn primary" data-action="close-modal">Done</button>`);}
function chooseFile(slot){const s=specOf(slot),input=document.createElement('input');input.type='file';input.accept=s.ext.map(x=>'.'+x).join(',');input.onchange=async()=>{if(!input.files[0])return;toast('Reading '+input.files[0].name+'…');try{const a=await inspectFile(input.files[0]);await commitAsset(slot,a,input.files[0],state.variant);modal.close();render();toast('Added '+s.short+'. '+statusLabel[statusFor(a,s)]+'.');}catch(err){toast('Could not add file: '+err.message);}};input.click();}
function invalidateReview(slot,variant){const targets=specOf(slot).group==='shared'?['A','B']:[variant];const reviewKey=slot==='lobby'?'lobby':specOf(slot).video?'video':slot.endsWith('Art')||slot==='logo'?'art':'accuracy';for(const v of targets)state.review[v+':'+reviewKey]=false;}
async function commitAsset(slot,asset,file,variant){const key=keyOf(slot,variant),previous=assets[key];assets[key]=asset;removed.delete(key);invalidateReview(slot,variant);let persisted=false;try{await storeFile(key,{meta:{...asset,url:undefined},file});persisted=true;}catch(err){storageOK=false;toast('Loaded for this session; browser storage could not save the file.');}if(previous?.custom&&previous.url!==asset.url)URL.revokeObjectURL(previous.url);save();return persisted;}
function importModal(){pending.forEach(p=>URL.revokeObjectURL(p.asset.url));pending=[];showModal('Import media','Choose your files, then confirm the slot for each asset.',`<div class="import-variant"><span>Artwork variant</span><select id="import-variant"><option value="A" ${state.variant==='A'?'selected':''}>Variant A</option><option value="B" ${state.variant==='B'?'selected':''}>Variant B</option></select></div><div class="dropzone" id="import-drop"><h3>Bring your island into the frame</h3><p>PNG, JPG, JPEG, MP4, MKV, WEBM or MOV · files stay on this device</p><button class="btn primary" data-action="browse-import">${icon('upload')}Choose files</button><input id="batch-input" type="file" accept=".png,.jpg,.jpeg,.mp4,.mkv,.webm,.mov" multiple hidden></div><div id="import-list" class="import-list"></div>`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" id="commit-import" data-action="commit-import" disabled>Add to workspace</button>`);}
async function readBatch(files){if(importBusy)return;importBusy=true;document.querySelector('#import-list').textContent='Reading file dimensions and video metadata…';try{for(const file of files){if(!/\.(png|jpe?g|mp4|mkv|webm|mov)$/i.test(file.name)){toast('Skipped unsupported file: '+file.name);continue;}if(file.size>450000000){toast('Skipped '+file.name+': over the supported upload size.');continue;}const asset=await inspectFile(file);if(!modal.open){URL.revokeObjectURL(asset.url);break;}pending.push({file,asset,slot:inferSlot(asset)});}if(modal.open)renderImportList();}finally{importBusy=false;}}
function renderImportList(){const list=document.querySelector('#import-list');if(!list)return;list.innerHTML=pending.map((p,i)=>`<div class="import-row">${p.asset.video?icon('news'):`<img src="${e(p.asset.url)}" alt="">`}<div><p>${e(p.file.name)}</p><small>${p.asset.width||'?'} × ${p.asset.height||'?'} · ${(p.file.size/1000000).toFixed(2)} MB</small></div><select data-import-index="${i}" aria-label="Destination for ${e(p.file.name)}"><option value="">Choose a slot…</option>${specs.filter(s=>!!s.video===!!p.asset.video).map(s=>`<option value="${s.id}" ${p.slot===s.id?'selected':''}>${e(s.name)}</option>`).join('')}</select></div>`).join('');document.querySelector('#commit-import').disabled=!pending.length;}
async function commitImport(){if(importBusy)return;const slots=pending.map(p=>p.slot);if(slots.some(x=>!x)){toast('Choose a destination slot for every file.');return;}if(new Set(slots).size!==slots.length){toast('Two files target the same slot. Choose a unique slot for each.');return;}importBusy=true;const btn=document.querySelector('#commit-import');btn.disabled=true;btn.textContent='Saving files…';try{const v=document.querySelector('#import-variant').value;for(const p of pending)await commitAsset(p.slot,p.asset,p.file,v);const count=pending.length;pending=[];state.variant=v;modal.close();render();toast(`${count} files added to the workspace.`);}finally{importBusy=false;}}
async function copyVariant(){const from=state.variant,to=from==='A'?'B':'A';showModal(`Copy variant ${from} to ${to}`,`This copies all five artwork slots. Existing ${to} artwork will be replaced; shared media is unaffected.`,`<p class="help">Missing slots in variant ${from} will also be empty in variant ${to}. This keeps each variant’s artwork set consistent.</p>`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-action="confirm-copy">Copy artwork set</button>`);}
async function confirmCopy(){const from=state.variant,to=from==='A'?'B':'A';const rows=await storedFiles();const stored=new Map(rows);for(const s of specs.filter(s=>s.group==='variant')){const src=assetOf(s.id,from),target=keyOf(s.id,to),prev=assets[target];if(prev?.custom)URL.revokeObjectURL(prev.url);if(src){const record=stored.get(keyOf(s.id,from));if(record){const url=URL.createObjectURL(record.file);assets[target]={...record.meta,url};await storeFile(target,record);}else{assets[target]={...src};await storeFile(target,{meta:{...src},file:null});}removed.delete(target);}else{delete assets[target];removed.add(target);await deleteFile(target);}}modal.close();render();toast(`Copied variant ${from} to ${to}.`);}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
async function exportPreview(){const node=document.querySelector(state.page==='compare'?'#comparison-capture':'#preview-stage');if(!node)return;const btn=document.querySelector('[data-action="export"]');btn.disabled=true;toast('Rendering preview…');try{await document.fonts.ready;for(const img of node.querySelectorAll('img')){if(!img.complete)await img.decode().catch(()=>{});}if(node.querySelector('video'))toast('Video export captures the current still frame; it is not a video file.');const blob=await window.htmlToImage.toBlob(node,{pixelRatio:Math.min(3,1920/node.clientWidth),backgroundColor:'#111517',skipFonts:true,cacheBust:false});if(!blob)throw Error('The browser did not produce an image');downloadBlob(blob,`discovery-${state.placement}-${state.page==='compare'?'A-vs-B':state.variant}.png`);toast('Preview PNG exported.');}catch(err){toast('Export failed: '+err.message);}finally{btn.disabled=false;}}
function exportReport(){const report={tool:'Discovery Studio 0.1',generatedAt:new Date().toISOString(),source:'Creator Portal requirements · October 11, 2026',profile:state.profile,island:state.title,creator:state.creator,note:'Technical file checks only; not a publishing approval. Media files are not included.',variants:Object.fromEntries(['A','B'].map(v=>[v,specs.map(s=>{const a=assetOf(s.id,v);return {slot:s.id,name:s.name,required:required(s,state.profile),status:statusFor(a,s),file:a?{name:a.name,width:a.width,height:a.height,sizeBytes:a.size,duration:a.duration,transparentPixels:a.alpha}:null,checks:checksFor(a,s)};})])),manualReview:state.review,composition:{placement:state.placement,mode:state.mode,crop:state.crop,logoPlacements:Object.fromEntries(placements.map(p=>[p.id,logoPlacement(state,p.id)])),lobbyCount:state.lobbyCount}};downloadBlob(new Blob([JSON.stringify(report,null,2)],{type:'application/json'}),'discovery-checklist.json');toast('Checklist exported with both variants.');}

document.addEventListener('click',async event=>{
 const b=event.target.closest('button');if(!b)return;
 if(b.dataset.page){state.page=b.dataset.page;if(state.page==='compare'&&state.placement==='lobby')state.placement='discover';render();return;}
 if(b.dataset.placement){state.placement=b.dataset.placement;state.useVideo=false;render();return;}
 if(b.dataset.variant){state.variant=b.dataset.variant;render();return;}
 if(b.dataset.upload){chooseFile(b.dataset.upload);return;}
 if(b.dataset.inspect){inspect(b.dataset.inspect);return;}
 if(b.dataset.remove){const slot=b.dataset.remove;showModal('Remove '+specOf(slot).short+'?', 'The original file on your device will not be changed.','<p class="help">This removes the asset from its workspace slot.</p>',`<button class="btn" data-action="close-modal">Cancel</button><button class="btn danger" data-action="confirm-remove" data-slot="${slot}">Remove asset</button>`);return;}
 switch(b.dataset.action){
 case 'import':importModal();break;
 case 'browse-import':document.querySelector('#batch-input').click();break;
 case 'commit-import':await commitImport();break;
 case 'close-modal':modal.close();break;
 case 'copy-variant':await copyVariant();break;
 case 'confirm-copy':try{const target=state.variant==='A'?'B':'A';for(const k of ['art','accuracy'])state.review[target+':'+k]=false;await confirmCopy();}catch(err){toast('Copy failed: '+err.message);}break;
 case 'confirm-remove':{const k=keyOf(b.dataset.slot),a=assets[k];if(a?.custom)URL.revokeObjectURL(a.url);delete assets[k];removed.add(k);invalidateReview(b.dataset.slot,state.variant);await deleteFile(k);modal.close();render();toast('Asset removed.');break;}
 case 'reset-crop':delete state.crop[cropKey(state,activeSlot())];render();break;
 case 'play-video':state.useVideo=!state.useVideo;updateStage();save();break;
 case 'report':exportReport();break;
 case 'export':await exportPreview();break;
 case 'expand':showModal(placement().label,'Expanded composition preview',`<div class="stage-wrap">${stageMarkup(state.variant,'expanded-stage')}</div>`);modal.classList.add('wide');break;
 }
});
document.addEventListener('change',async event=>{const el=event.target;if(el.id==='batch-input'){await readBatch([...el.files]);return;}if(el.dataset.importIndex!==undefined){pending[+el.dataset.importIndex].slot=el.value;return;}if(el.dataset.field){state[el.dataset.field]=el.type==='checkbox'?el.checked:el.dataset.field==='lobbyCount'?Number(el.value):el.value;if(el.dataset.field==='placement')state.useVideo=false;render();}if(el.dataset.review){state.review[state.variant+':'+el.dataset.review]=el.checked;save();}});
document.addEventListener('input',event=>{const el=event.target;if(el.dataset.text){state[el.dataset.text]=el.value;if(state.page==='preview')updateStage();save();}if(el.dataset.crop){const key=cropKey(state,activeSlot());state.crop[key]={x:50,y:50,zoom:100,...state.crop[key],[el.dataset.crop]:+el.value};document.querySelector('#out-crop-'+el.dataset.crop).textContent=el.value+'%';updateStage();save();}if(el.dataset.logo){state.logoPlacements[state.placement]={...logoPlacement(state),[el.dataset.logo]:+el.value};document.querySelector('#out-logo-'+el.dataset.logo).textContent=el.value+'%';updateStage();save();}});
document.addEventListener('dragover',event=>{const target=event.target.closest('[data-drop-slot],#import-drop');if(target){event.preventDefault();target.classList.add('dragging');}});
document.addEventListener('dragleave',event=>{event.target.closest('[data-drop-slot],#import-drop')?.classList.remove('dragging');});
document.addEventListener('drop',async event=>{const target=event.target.closest('[data-drop-slot],#import-drop');if(!target)return;event.preventDefault();target.classList.remove('dragging');const files=[...event.dataTransfer.files];if(target.id==='import-drop'){await readBatch(files);return;}if(files.length!==1){toast('Drop one file per slot, or use Import media for a batch.');return;}const slot=target.dataset.dropSlot;try{const a=await inspectFile(files[0]);await commitAsset(slot,a,files[0],state.variant);render();toast('Added '+specOf(slot).short+'. '+statusLabel[statusFor(a,specOf(slot))]+'.');}catch(err){toast('Import failed: '+err.message);}});
modal.addEventListener('close',()=>{for(const p of pending)URL.revokeObjectURL(p.asset.url);pending=[];modal.innerHTML='';});
document.addEventListener('error',event=>{if(event.target instanceof HTMLVideoElement)toast('This browser cannot play this video codec. The file is retained for manual review.');},true);

async function init(){
 try{const response=await fetch('assets/manifest.json');if(!response.ok)throw Error('Starter asset manifest is unavailable');const seed=await response.json();for(const [key,value] of Object.entries(seed)){if(!removed.has(key))assets[key]=value;}}catch(err){toast(err.message);}
 try{await openStorage();for(const [key,row] of await storedFiles()){if(!removed.has(key))assets[key]={...row.meta,url:row.file?URL.createObjectURL(row.file):row.meta.url};}}catch{storageOK=false;}
 render();
}
init();
